import { sql, type SQL } from "drizzle-orm";

/**
 * A lease a worker holds on a queue row: the `claim_token` its claim wrote, and the counter the claim raised. Each claim
 * writes a fresh token, so a worker whose lease ran out cannot settle the row of a later claim, even after a requeue
 * reset the counter.
 */
export interface Claim {
  claimToken: string;
  attempts: number;
}

/** A fresh claim token, generated by the database in the statement that takes the lease. */
export const NEW_CLAIM_TOKEN = sql`gen_random_uuid()`;

/**
 * The fence every statement that ends or uses a claim filters with: the row still carries this claim's token and
 * counter. `alias` names the table as the statement does (`ai_jobs` in a Drizzle update, `u`, `sr`, `ev` in raw SQL).
 *
 * The counter comparison covers a deploy that runs old and new workers side by side: an old worker claims without
 * writing a token, so the row keeps the previous claim's token, and only the raised counter tells the two claims apart.
 * Drop it once no worker of the old version runs.
 */
export function heldBy(alias: string, claim: Claim, counter = "attempts"): SQL {
  const table = sql.identifier(alias);
  return sql`(${table}.claim_token = ${claim.claimToken}::uuid and ${table}.${sql.identifier(counter)} = ${claim.attempts})`;
}
